import { useId, type HTMLAttributes, type ReactNode } from "react";

export function HoverCard({ trigger, children, className = "" }: { trigger: ReactNode; children: ReactNode; className?: string }) { const id = useId(); return <span className={`co-group co-relative co-inline-block ${className}`.trim()}><span tabIndex={0} aria-describedby={id} className="co-outline-none focus-visible:co-ring-2">{trigger}</span><span role="tooltip" id={id} className="co-invisible co-absolute co-start-0 co-z-40 co-mt-2 co-w-72 co-rounded-lg co-border co-border-black/15 co-bg-white co-p-4 co-opacity-0 co-shadow-lg co-transition group-hover:co-visible group-hover:co-opacity-100 group-focus-within:co-visible group-focus-within:co-opacity-100">{children}</span></span>; }
export function HoverCardContent(props: HTMLAttributes<HTMLSpanElement>) { return <span {...props} />; }
